    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configurez les paramètres système : URL de base, sécurité, langue par défaut, fuseau horaire, valeurs par défaut de l\'évaluation des risques, etc.',
    'SettingsPreferencesDesc'             => 'Valeurs par défaut et préférences de comportement dans SimpleRisk : langue, fuseau horaire, statuts d\'audit, exigences de cartographie des risques, options de comportement de l\'interface, et autres.',
    'SettingsFileUploadDesc'              => 'Types de fichiers autorisés au téléversement et limites de taille pour les différents champs de pièces jointes.',
    'SettingsMailDesc'                    => 'Configuration SMTP pour les notifications par e-mail sortantes, y compris le transport, l\'hôte, l\'authentification et l\'adresse de réponse.',
    'SettingsBackupsDesc'                 => 'Configurez la durée de conservation, la planification et les liens de téléchargement des sauvegardes de la base de données SimpleRisk.',
    'SettingsSecurityDesc'                => 'Paramètres d\'authentification, de session, de politique de mot de passe, d\'URL de base et de sécurité de l\'API.',
    'SettingsLoggingDesc'                 => 'Configuration de la journalisation de débogage et d\'audit : niveaux de journalisation, durée de conservation et emplacement des fichiers journaux.',
    'HealthCheckDesc'                     => 'Diagnostiquez l\'état du système : version de PHP, extensions, autorisations des fichiers, connectivité à la base de données, planification cron et activations des modules complémentaires.',
    'AnnouncementsDesc'                   => 'Rédigez et gérez les annonces de type bannière visibles par tous les utilisateurs.',
    'RegisterAndUpgradeDesc'              => 'Enregistrez votre installation SimpleRisk, saisissez ou renouvelez une clé d\'abonnement et déclenchez des mises à niveau Core/Extra en un clic.',
    'QueueMonitorDesc'                    => 'Examinez la file d\'attente des tâches en arrière-plan : tâches en attente, en cours d\'exécution et ayant échoué.',
    'ExtrasDesc'                          => 'Activez, désactivez et configurez les modules complémentaires (Extras) de SimpleRisk (extensions payantes).',
    'ArtificialIntelligenceExtraDesc'     => 'Le module complémentaire Intelligence artificielle fournit une analyse des risques améliorée (y compris des évaluations FAIR) et une documentation personnalisée.',
    'CustomizationExtraDesc'              => 'Le module complémentaire Personnalisation permet d\'ajouter et de supprimer différents types de champs et de créer dynamiquement des modèles de page personnalisés.',
    'NotificationExtraDesc'               => 'Le module complémentaire Notifications par e-mail permet à SimpleRisk d\'envoyer des notifications par e-mail lorsque des risques sont soumis, modifiés ou traités d\'une autre manière. Ce module peut aussi être ajouté comme script planifié pour envoyer des rappels périodiques lorsque des risques sont prêts pour une revue de gestion. Dans le produit SimpleRisk Core, sans ce module complémentaire, aucune notification n\'est communiquée en dehors de l\'outil lui-même.',
    'VulnerabilityManagementExtraDesc'    => 'Le module complémentaire Gestion des vulnérabilités permet aux clients d\'intégrer leur instance SimpleRisk avec Qualys, Tenable.io ou Rapid7 Nexpose/InsightVM et d\'importer dans SimpleRisk les données d\'actifs et de vulnérabilités. Vous pouvez ensuite sélectionner les sites à couvrir, déterminer quels scores de vulnérabilité doivent être importés et trier les vulnérabilités à transformer en risques afin de les suivre.',
    'IncidentManagementExtraDesc'         => 'Le module complémentaire Gestion des incidents est basé sur le guide NIST 800-61 de gestion des incidents de sécurité informatique et offre des fonctionnalités de gestion des incidents directement dans le système SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Renommer la terminologie SimpleRisk (Risque, Actif, Cadre, etc.) dans toute l\'interface utilisateur.',
    'RiskConfigurationDesc'               => 'Configurez les règles de calcul du score de risque : niveaux, appétence, seuils de SLA et formules de risque classique / contributif.',
    'RiskAndThreatCatalogDesc'            => 'Tenir à jour le catalogue des valeurs de risque et de menace utilisées dans les listes déroulantes.',
    'AddAndRemoveValuesDesc'              => 'Gérez les valeurs des listes déroulantes pour les champs de risque : emplacement, source, catégorie, équipe, technologie, etc.',
    'AssetValuationDesc'                  => 'Configurez l\'échelle de valorisation des actifs et les remplacements de valorisation par actif.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Ajouter, modifier, désactiver et réinitialiser les utilisateurs ; gérer la politique de mots de passe.',
    'RoleManagementDesc'                  => 'Définissez les rôles et les autorisations que chaque rôle confère.',
    'TeamManagementDesc'                  => 'Créer et gérer des équipes utilisées pour le filtrage de la visibilité des enregistrements.',
    'SeparationExtraDesc'                 => 'Le module complémentaire Séparation par équipe limite l\'affichage des risques aux seuls utilisateurs membres de l\'équipe à laquelle le risque est assigné. Dans le produit SimpleRisk Core, sans ce module complémentaire, chaque utilisateur peut voir tous les risques.',
    'CustomAuthenticationExtraDesc'       => 'L\'extension d\'authentification personnalisée prend en charge l\'authentification Active Directory et SAML. Dans la version de base de SimpleRisk, sans cette extension, la seule option consiste à créer de nouveaux utilisateurs dans le référentiel d\'identités SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Le module complémentaire Base de données chiffrée génère une clé de chiffrement AES-256 bits aléatoire, puis l\'utilise pour chiffrer le texte sensible avant son insertion dans la base de données SimpleRisk. Cela empêche toute personne de voir ou de modifier les données sans passer directement par l\'application SimpleRisk.',
    'OrganizationManagementDesc'          => 'Le module complémentaire Hiérarchie organisationnelle permet de définir plusieurs unités d\'affaires pouvant inclure un nombre quelconque d\'équipes. Les utilisateurs peuvent ensuite être affectés à une ou plusieurs équipes de différentes unités d\'affaires. Cela influe sur la capacité d\'un utilisateur à voir et à utiliser les équipes, les utilisateurs et les actifs auxquels il n\'est pas associé.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Suppression en masse des risques. À utiliser avec modération — les suppressions sont définitives.',
    'AuditTrailDesc'                      => 'Recherchez et exportez le journal d\'audit système des actions des utilisateurs.',
    'ImportExportExtraDesc'               => 'L\'extension Import-Export permet d\'importer des données dans SimpleRisk en faisant correspondre les champs d\'un fichier CSV aux champs de la base de données SimpleRisk. Elle peut servir à importer les résultats d\'audit d\'une feuille de calcul tierce, les résultats d\'analyses de vulnérabilité d\'un autre outil, les actifs de votre CMDB, etc. Cette extension permet également d\'exporter des fichiers CSV depuis SimpleRisk contenant les risques, les mesures d\'atténuation, les revues ou un rapport combinant ces trois éléments.',
    'JiraExtraDesc'                       => 'Le module complémentaire Intégration Jira permet aux utilisateurs d\'intégrer de façon bidirectionnelle une instance Jira. Il permet de relier des risques à des problèmes Jira, ainsi que de synchroniser leurs données, leur statut et leurs commentaires.',
    'APIExtraDesc'                        => 'L\'API Extra permet aux clients d\'utiliser une API RESTful pour créer des interactions scriptées avec d\'autres applications afin de bénéficier d\'une automatisation avancée et de tirer parti de l\'infrastructure existante.',
    'AdvancedSearchExtraDesc'             => 'Le module complémentaire Recherche avancée transforme la zone de recherche de la barre supérieure en une recherche unique portant sur les risques, cadres, contrôles, documents, exceptions, tests, audits, actifs et groupes d\'actifs, avec une page de recherche complète pour parcourir les résultats. Il n\'affiche que les enregistrements que l\'utilisateur est autorisé à voir.',
    'AssessmentsExtraDesc'                => 'Le module complémentaire Évaluation des risques permet aux utilisateurs de définir des contacts, de créer des questions (y compris avec logique conditionnelle), d\'assembler plusieurs questions dans un modèle de questionnaire, de créer des questionnaires et de les envoyer aux contacts, de voir les résultats des questionnaires, d\'ajouter des risques à partir de ces résultats, de comparer les résultats dans le temps, d\'importer et d\'exporter des évaluations personnalisées en externe, et de consulter la piste d\'audit de l\'évaluation des risques.',
    'ActiveAssessmentsDesc'               => 'Consultez et gérez les évaluations en cours.',
    'WorkflowsExtraDesc'                  => 'L\'extension Workflows offre un moteur de workflow visuel et événementiel qui automatise les actions de gestion des risques en réponse aux événements survenant dans SimpleRisk. Vous pouvez concevoir des workflows qui se déclenchent lors de modifications (par exemple, la soumission, la mise à jour ou la révision d\'un risque) afin d\'acheminer les approbations, d\'attribuer les tâches et de maintenir le bon déroulement de votre processus sans intervention manuelle.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'L\'Extra Secure Controls Framework (SCF) est une intégration directe entre le Secure Controls Framework et SimpleRisk. Il importe le catalogue de contrôles du SCF et leurs cartographies à travers un large éventail de cadres de conformité et de cybersécurité dans la fonctionnalité Gouvernance de SimpleRisk, afin que vous puissiez adopter les cadres dont vous avez besoin et gérer leurs contrôles sans avoir à les créer manuellement.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migrer les colonnes de dates de révision héritées de type varchar vers des types de date appropriés. Visible uniquement en cas de besoin.',
    'DatabaseUpgradeDesc'                 => 'Déclenchez manuellement la routine de mise à niveau de la base de données SimpleRisk.',

