    'EncryptionNoBackupAvailable'           => 'Aucune sauvegarde antérieure à l\'activation n\'est actuellement conservée. La sauvegarde est créée au début de chaque activation et écrasée lors de toute activation ou désactivation ultérieure.',
    'EncryptionRestoreCtaHelp'              => 'Choisissez cette option si la validation a détecté des problèmes et que vous devez revenir à l\'état antérieur au chiffrement.',
    'EncryptionRestoreTitle'                => 'Restaurer à partir d\'une sauvegarde ?',
    'EncryptionRestoreBodyWhy'              => 'Retour à l\'instantané antérieur au chiffrement, capturé au début de la dernière activation. Choisissez cette option si la validation effectuée après l\'activation a révélé des problèmes et que vous devez abandonner le chiffrement.',
    'EncryptionRestoreBodyWhat'             => 'Chaque ligne écrite dans la base de données après la création de la sauvegarde sera définitivement perdue, y compris les risques, les mitigations, les entrées du journal d\'audit et toute autre modification effectuée depuis l\'activation. L\'Extra Base de données chiffrée sera désactivé dans le cadre de la restauration.',
    'EncryptionDeleteBackupCta'             => 'Supprimer la sauvegarde antérieure au chiffrement',
    'EncryptionDeleteBackupCtaHelp'         => 'Choisissez cette option une fois la validation post-chiffrement terminée. La suppression de l\'instantané non chiffré est ce qui rend le chiffrement réellement protecteur.',
    'EncryptionDeleteBackupTitle'           => 'Supprimer la sauvegarde antérieure au chiffrement ?',
    'EncryptionDeleteBackupBodyWhy'         => 'Suppression de l\'instantané non chiffré de vos données, capturé au début de la dernière activation. Le conserver indéfiniment va à l\'encontre de l\'objectif du chiffrement : toute personne disposant d\'un accès à la base de données peut lire la copie antérieure au chiffrement.',
    'EncryptionDeleteBackupBodyWhat'        => 'La sauvegarde stockée dans la base de données est supprimée immédiatement. Vous ne pourrez plus utiliser Restaurer à partir de la sauvegarde pour ramener la base de données à l\'état antérieur au chiffrement. Si vous constatez ultérieurement des problèmes liés au chiffrement, votre seule option de récupération sera une restauration complète de la base de données à partir de vos sauvegardes opérationnelles.',
    'EncryptionDeleteBackupError'           => 'Échec de la suppression de la sauvegarde. Vérifiez le journal de débogage et réessayez.',
