    // refers to.
    'SoaMissingFieldsTitle' => 'Les informations de couverture de cette déclaration sont manquantes',
    'SoaMissingScopeStatement' => 'Aucune déclaration de périmètre n\'a été enregistrée pour ce cadre. Une DdA devrait indiquer le périmètre sur lequel elle porte.',
    'SoaMissingInclusionJustification' => 'Aucune justification d\'inclusion par défaut n\'a été enregistrée. Les contrôles applicables sans risques associés se référeront à une déclaration générique plutôt qu\'à la vôtre.',
    'SoaEditFrameworkToAdd' => 'Ajoutez-les sur le cadre',

    // Opened from the Reporting Hub, which cannot supply a framework. A picker,
