    'SoaNoControls' => 'Ce cadre ne contient aucun contrôle',
    'SoaNoControlsHint' => 'Associez des contrôles au cadre et sa déclaration d\'applicabilité les listera.',

    // The second half of the statement-of-applicability launcher's affordance
    // row, beside "Open in browser" and the existing 'DownloadAsXLSX'. Rendered
