    'EncryptionPipelineStalledTask' => 'Un pipeline de chiffrement (tâche n° {$id}, {$type}) semble bloqué : son statut est {$status} depuis un temps anormalement long, sans progression. Cela signifie généralement que le worker de la file d\'attente en arrière-plan n\'est pas en cours d\'exécution ; vérifiez qu\'il est planifié, puis réessayez une fois qu\'il aura traité la tâche bloquée.',
    'EncryptionPipelineStalledState' => 'Un pipeline de chiffrement semble bloqué : il est marqué en cours depuis un temps anormalement long, sans tâche en arrière-plan correspondante. Cela signifie généralement que le worker de la file d\'attente n\'est pas en cours d\'exécution, ou qu\'un pipeline précédent s\'est terminé sans mettre à jour correctement cet état. Vérifiez le journal de débogage avant de réessayer.',
