    'UpgradeCorrectionUnknownVersionGuidance' => 'Définissez le paramètre db_version sur la version dont le schéma correspond réellement à cette base de données, puis exécutez à nouveau la mise à niveau : UPDATE settings SET value=\'<release>\' WHERE name=\'db_version\'. Si la valeur est un espace réservé tel que 2026XXXX-001, la valeur correcte est presque toujours la version réelle la plus récente qui était installée avant l\'exécution de la mise à niveau.',
