    'AssetScoring' => 'Évaluation des actifs',
    'AssetScoringSettingsHint' => 'Chaque actif est évalué Faible, Modéré ou Élevé pour la confidentialité, l\'intégrité et la disponibilité, et la confidentialité peut aussi être Non applicable, ce qui l\'exclut des deux résultats. Sa catégorisation FIPS correspond à la plus élevée des trois évaluations. Son score pondéré est la moyenne pondérée des trois valeurs de niveau, et les seuils de tranche transforment ce score en tranche Faible, Modérée ou Élevée. La modification de ces paramètres recalcule immédiatement le score de tous les actifs.',
    'Weights' => 'Pondérations',
    'AssetScoringWeightsHint' => 'Poids de chaque objectif dans le score pondéré : de 0 à 100, avec jusqu\'à deux décimales. Une pondération de 0 exclut cet objectif. L\'intégrité et la disponibilité ne peuvent pas être toutes deux à 0, car une confidentialité Non applicable est toujours exclue.',
    'LevelValues' => 'Valeurs de niveau',
    'AssetScoringLevelValuesHint' => 'Le nombre que chaque évaluation apporte au score pondéré : supérieur à 0 et jusqu\'à 100, avec jusqu\'à deux décimales, et Faible inférieur à Modéré, lui-même inférieur à Élevé. Les valeurs par défaut sont Faible 1, Modéré 2 et Élevé 3.',
    'BandThresholds' => 'Seuils de tranche',
    'AssetScoringBandThresholdsHint' => 'Un score pondéré égal ou supérieur à un seuil appartient à cette catégorie, et un score inférieur au seuil « Modéré » est « Faible ». La catégorie « Modéré » doit commencer au-dessus de la valeur « Faible », et la catégorie « Élevé » doit commencer au-dessus de « Modéré » sans dépasser la valeur « Élevé ».',
    'ModerateStartsAt' => 'Modéré commence à',
