    'AssetScoringDefaultsHint' => 'Présélectionne ces évaluations lorsqu\'une personne ajoute un actif dans le formulaire d\'actif. Les actifs créés par découverte, import ou l\'API restent sans score, sauf s\'ils fournissent leurs propres évaluations. Laissez les trois sur Non défini pour désactiver cette option.',
