    'AssetScoringThresholdsInvalid' => 'Les seuils de tranche du score des actifs doivent avoir au plus deux décimales, Modéré commençant au-dessus de la valeur Faible, Élevé commençant au-dessus de Modéré, et Élevé ne commençant pas au-dessus de la valeur Élevé.',
